// decryptRequest handles decryption if XKey is present
func (h *RequestHandler) decryptRequest(r micro.Request) ([]byte, error) {
	xkey := r.Headers().Get("Nats-Server-Xkey")
	if len(xkey) == 0 {
		return r.Data(), nil
	}

	if h.curveKeyPair == nil {
		return nil, fmt.Errorf("xkey not supported")
	}

	return h.curveKeyPair.Open(r.Data(), xkey)
}

// signUserClaims signs the user claims with the issuer key
func (h *RequestHandler) signUserClaims(claims *jwt.UserClaims) (string, error) {
	return claims.Encode(h.issuerKeyPair)
}

