@staticmethod
async def _relay_reconnects(nats_client, queue: asyncio.Queue, item) -> None:
    """Put ``item`` on ``queue`` after every reconnect of ``nats_client``.

    Clients without a ``reconnected`` signal (plain ``nats.NATS``, test doubles)
    never relay anything.
    """
    signal = getattr(nats_client, "reconnected", None)
    if signal is None:
        return
    while True:
        await signal.wait()
        await queue.put(item)

